438	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_gpt::prefill(const std::string& input_text, const ncnn::Mat& bgr, const std::shared_ptr<ncnn_llm_gpt_ctx> ctx) const {
439	    std::shared_ptr<ncnn_llm_gpt_ctx> new_ctx = clone_ctx(ctx);
440	
441	    ncnn::Mat image_embeds;
442	    int num_patches_w = 0;
443	    int num_patches_h = 0;
444	    get_visiual_features(bgr, image_embeds, num_patches_w, num_patches_h);
445	
446	    const int image_embeds_size = image_embeds.h;
447	
448	    auto token_ids = bpe->encode(input_text, false, false);
449	    int last_token_id = token_ids.back();
450	    token_ids.pop_back();
451	
452	    ncnn::Mat input_ids_mat = ncnn::Mat((int)token_ids.size(), 1, (void*)token_ids.data()).clone();
453	    ncnn::Mat token_embed;
454	    {
