923	            for (int i = 0; i < attn_cnt; ++i) {
924	                char kname[16], vname[16];
925	                std::snprintf(kname, sizeof(kname), "cache_k%d", i);
926	                std::snprintf(vname, sizeof(vname), "cache_v%d", i);
927	                ex.input(kname, ctx->kv_cache[i].first);
928	                ex.input(vname, ctx->kv_cache[i].second);
929	            }
930	
931	            for (int i = 0; i < sconv_cnt; ++i) {
932	                char name[16];
933	                std::snprintf(name, sizeof(name), "cache_conv%d", i);
934	                ex.input(name, qwen_ctx->sconv_cache[i]);
935	            }
936	            for (int i = 0; i < gdr_cnt; ++i) {
937	                char name[16];
938	                std::snprintf(name, sizeof(name), "cache_gdr%d", i);
939	                ex.input(name, qwen_ctx->gdr_cache[i]);
940	            }
941	
942	            for (int i = 0; i < attn_cnt; ++i) {
943	                char kname[32], vname[32];
944	                std::snprintf(kname, sizeof(kname), "out_cache_k%d", i);
945	                std::snprintf(vname, sizeof(vname), "out_cache_v%d", i);
946	                ncnn::Mat k_cache, v_cache;
947	                ex.extract(kname, k_cache);
948	                ex.extract(vname, v_cache);
949	                ctx->kv_cache[i] = { std::move(k_cache), std::move(v_cache) };
950	            }
951	
952	            for (int i = 0; i < sconv_cnt; ++i) {
953	                char name[32];
954	                std::snprintf(name, sizeof(name), "out_cache_conv%d", i);
955	                ncnn::Mat cache;
956	                ex.extract(name, cache);
957	                qwen_ctx->sconv_cache[i] = std::move(cache);
958	            }
959	            for (int i = 0; i < gdr_cnt; ++i) {
960	                char name[32];
961	                std::snprintf(name, sizeof(name), "out_cache_gdr%d", i);
962	                ncnn::Mat cache;
963	                ex.extract(name, cache);
964	                qwen_ctx->gdr_cache[i] = std::move(cache);
965	            }
966	
967	            ex.extract("out0", decode_out);
968	        }
969	
970	        ncnn::Mat logits_mat = llm_run_lm_head(*proj_out_net, decode_out);
971	
972	        LlmTokenSampleConfig sample_cfg;
973	        sample_cfg.vocab_size = vocab_size;
974	        sample_cfg.temperature = cfg.temperature;
975	        sample_cfg.top_p = cfg.top_p;
976	        sample_cfg.top_k = cfg.top_k;
977	        sample_cfg.repetition_penalty = cfg.repetition_penalty;
978	        sample_cfg.do_sample = cfg.do_sample;
979	        int next_id = llm_select_next_token(logits_mat, history, sample_cfg);
980	
981	        ctx->cur_token = next_id;
982	        history.insert(next_id);
983	    }
984	    return ctx;
985	}
