1084	ncnn::Mat ncnn_llm_gpt::reorder_patches_for_merge(const ncnn::Mat& pixel_values, int h_patches, int w_patches, int merge_size) const {
1085	    int num_patches = pixel_values.h;
1086	    int feature_dim = pixel_values.w;
1087	
1088	    if (num_patches != h_patches * w_patches) return ncnn::Mat();
1089	
1090	    int grid_h = h_patches / merge_size;
1091	    int grid_w = w_patches / merge_size;
1092	
1093	    ncnn::Mat reordered_pixel_values(feature_dim, num_patches, (size_t)4u);
1094	    int new_row_idx = 0;
1095	
1096	    for (int gh = 0; gh < grid_h; gh++) {
1097	        for (int gw = 0; gw < grid_w; gw++) {
1098	            for (int mh = 0; mh < merge_size; mh++) {
1099	                for (int mw = 0; mw < merge_size; mw++) {
1100	                    int original_h = gh * merge_size + mh;
1101	                    int original_w = gw * merge_size + mw;
1102	                    int original_row_idx = original_h * w_patches + original_w;
1103	
1104	                    const float* src_ptr = pixel_values.row(original_row_idx);
1105	                    float* dst_ptr = reordered_pixel_values.row(new_row_idx);
1106	                    memcpy(dst_ptr, src_ptr, feature_dim * sizeof(float));
1107	                    new_row_idx++;
1108	                }
1109	            }
1110	        }
1111	    }
1112	    return reordered_pixel_values;
1113	}
