1206	    }
1207	
1208	    if (vision_embed_pos) {
1209	        ncnn::Mat pos_embeds;
1210	        {
1211	            ncnn::Mat grid(num_patches_w, num_patches_h);
1212	            ncnn::Extractor ex = vision_embed_pos->create_extractor();
