1228	            ex.input("in3", emb_sin);
1229	            ex.extract("out0", image_embeds);
1230	        }
1231	        return 0;
1232	    }
1233	
1234	    ncnn::Mat emb_cos, emb_sin;
1235	    generate_vision_rope_cache_2d(num_patches_h, num_patches_w, spatial_merge_size,
