135	    std::string out;
136	    out.reserve(s.size());
137	    auto is_cont = [&](unsigned char c) { return (c & 0xC0) == 0x80; };
138	    for (size_t i = 0; i < s.size();) {
139	        unsigned char c = static_cast<unsigned char>(s[i]);
140	        if (c < 0x80) { out.push_back(static_cast<char>(c)); ++i; continue; }
141	        if ((c >> 5) == 0x6 && i + 1 < s.size() && is_cont(static_cast<unsigned char>(s[i+1]))) {
142	            out.append(s, i, 2); i += 2; continue;
143	        }
144	        if ((c >> 4) == 0xE && i + 2 < s.size() &&
145	            is_cont(static_cast<unsigned char>(s[i+1])) &&
146	            is_cont(static_cast<unsigned char>(s[i+2]))) {
147	            out.append(s, i, 3); i += 3; continue;
148	        }
149	        if ((c >> 3) == 0x1E && i + 3 < s.size() &&
150	            is_cont(static_cast<unsigned char>(s[i+1])) &&
151	            is_cont(static_cast<unsigned char>(s[i+2])) &&
152	            is_cont(static_cast<unsigned char>(s[i+3]))) {
153	            out.append(s, i, 4); i += 4; continue;
154	        }
155	        out.push_back('?');
156	        ++i;
157	    }
158	    return out;
